/**
 * The conversation screen, with a thread above a composer (`design/archetypes/conversation-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/conversation-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onCleanup, onMount, type JSX } from 'solid-js'

import {
  claimSlot,
  createCell,
  createDerived,
  devWarning,
  elementRef,
  resolveSlot,
  scope,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/conversation-page.module.css'
import Button from '../controls/Button'
import Drawer from '../overlays/Drawer'
import PageHeader from '../structure/PageHeader'
import SplitPane from '../layout/SplitPane'

export interface ConversationPageProps {
  /**
   * Vocabulary controls with at most one primary, joined by the aside's toggle below the
   * breakpoint.
   */
  actions?: JSX.Element
  /**
   * An ArtifactPane, beside the thread at wide widths and in a Drawer below the breakpoint.
   */
  aside?: JSX.Element
  /**
   * The aside's name, used for the separator, the drawer's title and the toggle's label.
   */
  asideLabel?: string
  /**
   * A PromptInput.
   */
  composer: JSX.Element
  description?: string
  /**
   * A ChatThread.
   */
  thread: JSX.Element
  title: string
}

/** The conversation screen, with a thread above a composer. */
export default function ConversationPage(given: ConversationPageProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const root = elementRef<HTMLElement>()
    const actionsSlot = resolveSlot(() => props.actions)
    const asideSlot = resolveSlot(() => props.aside)
    const narrow = createCell(false)
    const asideOpen = createCell(false)
    const measure = createDerived(() => () => {
      if (root.value === null) return
      const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
      const below = root.value.getBoundingClientRect().width < 48 * rem
      narrow.value = below
      if (!below) asideOpen.value = false
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        measure.value()
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [root.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      devWarning(
        Boolean(asideSlot.filled()) && props.asideLabel === undefined,
        'ConversationPage: an `aside` needs an `asideLabel`, which names the split’s separator, the drawer and its toggle.',
      )
    }
    onMount(effect2)
    return (
      <div
        class={styles.page}
        data-aside={asideSlot.filled() ? (narrow.value ? 'drawer' : 'split') : undefined}
        data-member="conversation-page"
        ref={root.attach}
      >
        <PageHeader
          title={props.title}
          description={props.description}
          actions={
            actionsSlot.filled() || (asideSlot.filled() && narrow.value) ? (
              <>
                {actionsSlot()}
                {asideSlot.filled() && narrow.value ? (
                  <Button
                    variant="outline"
                    tone="neutral"
                    size="sm"
                    icon="artifact"
                    label={props.asideLabel ?? ''}
                    onClick={() => (asideOpen.value = true)}
                  />
                ) : null}
              </>
            ) : undefined
          }
        />
        {/* body */}
        <div class={styles.body}>
          {asideSlot.filled() && !narrow.value ? (
            <SplitPane
              label={props.asideLabel ?? ''}
              defaultRatio={0.58}
              startMin={320}
              endMin={280}
              start={
                <div class={styles.conversation}>
                  {/* thread */}
                  <div class={styles.thread}>{props.thread}</div>
                  {/* composer */}
                  <div class={styles.composer}>{props.composer}</div>
                </div>
              }
              end={<div class={styles.aside}>{asideSlot()}</div>}
            />
          ) : (
            <div class={styles.conversation}>
              {/* thread */}
              <div class={styles.thread}>{props.thread}</div>
              {/* composer */}
              <div class={styles.composer}>{props.composer}</div>
            </div>
          )}
        </div>
        {asideSlot.filled() && narrow.value ? (
          <Drawer
            side="end"
            size="lg"
            title={props.asideLabel ?? ''}
            open={asideOpen.value}
            onOpenChange={($event) => (asideOpen.value = $event)}
          >
            {/* drawerAside */}
            <div class={styles.drawerAside}>{asideSlot()}</div>
          </Drawer>
        ) : null}
      </div>
    )
  })
}
